if(!function_exists('mvm_ai_agenda_settings_v1')){function mvm_ai_agenda_settings_v1(){ $d=['enabled'=>false,'batch'=>2,'cursor'=>0,'last_run'=>0,'last_message'=>'Nog niet uitgevoerd.','radar_sort'=>'recent'];$v=get_option('mvm_hub_ai_agenda_v1',[]);return wp_parse_args(is_array($v)?$v:[],$d);}}
