if(!function_exists('mvm_ai_agenda_abs_url_v1')){function mvm_ai_agenda_abs_url_v1($url,$base){$url=trim((string)$url);if($url==='')return '';if(preg_match('#^https?://#i',$url))return esc_url_raw($url);$bp=wp_parse_url($base);if(!is_array($bp)||empty($bp['host']))return '';if(str_starts_with($url,'//'))return esc_url_raw(($bp['scheme']??'https').':'.$url);$root=($bp['scheme']??'https').'://'.$bp['host'].(!empty($bp['port'])?':'.$bp['port']:'');if(str_starts_with($url,'/'))return esc_url_raw($root.$url);$path=$bp['path']??'/';$dir=preg_replace('#/[^/]*$#','/',$path);return esc_url_raw($root.$dir.$url);}}
if(!function_exists('mvm_ai_agenda_fetch_v1')){function mvm_ai_agenda_fetch_v1($url){$r=wp_safe_remote_get($url,['timeout'=>7,'redirection'=>3,'user-agent'=>'MvM-Hub-AgendaCrawler/1.0 (+'.home_url('/').')','headers'=>['Accept'=>'text/html,application/xhtml+xml']]);if(is_wp_error($r))return $r;$code=(int)wp_remote_retrieve_response_code($r);if($code<200||$code>=400)return new WP_Error('mvm_agenda_http','HTTP '.$code);$body=(string)wp_remote_retrieve_body($r);return $body!==''?substr($body,0,900000):new WP_Error('mvm_agenda_empty','Lege bronpagina.');}}
if(!function_exists('mvm_ai_agenda_events_v1')){function mvm_ai_agenda_events_v1($html,$base){$out=[];if(!preg_match_all('~<script[^>]+type=["\']application/ld\+json["\'][^>]*>(.*?)</script>~is',$html,$m))return $out;$walk=function($v)use(&$walk,&$out,$base){if(!is_array($v))return;$type=$v['@type']??'';$types=array_map('strtolower',(array)$type);if(in_array('event',$types,true)){ $title=trim(wp_strip_all_tags((string)($v['name']??$v['headline']??'')));if($title!==''){ $url=mvm_ai_agenda_abs_url_v1((string)($v['url']??''),$base);$out[]=['title'=>$title,'url'=>$url?:$base,'start'=>(string)($v['startDate']??''),'end'=>(string)($v['endDate']??''),'published'=>(string)($v['datePublished']??''),'excerpt'=>mb_substr(wp_strip_all_tags((string)($v['description']??'')),0,1600)];}}foreach($v as $x)if(is_array($x))$walk($x);};foreach($m[1] as $raw){$j=json_decode(html_entity_decode($raw,ENT_QUOTES|ENT_HTML5,'UTF-8'),true);if(is_array($j))$walk($j);if(count($out)>=12)break;}return array_slice($out,0,12);}}
if(!function_exists('mvm_ai_agenda_discover_v1')){function mvm_ai_agenda_discover_v1($html,$base){if(!class_exists('DOMDocument'))return '';$d=new DOMDocument();libxml_use_internal_errors(true);@$d->loadHTML('<?xml encoding="utf-8" ?>'.substr($html,0,650000));$xp=new DOMXPath($d);$links=$xp->query('//a[@href]');if(!$links)return '';foreach($links as $a){$href=(string)$a->getAttribute('href');$text=trim(preg_replace('/\s+/u',' ',$a->textContent));$hay=strtolower(remove_accents($href.' '.$text));if(!preg_match('/\b(agenda|evenementen?|activiteiten|kalender|events?)\b/u',$hay))continue;$u=mvm_ai_agenda_abs_url_v1($href,$base);if($u&&wp_http_validate_url($u))return $u;}return '';}}
if(!function_exists('mvm_ai_agenda_published_v1')){function mvm_ai_agenda_published_v1($html){$c=[];$add=function($raw,$source,$score)use(&$c){$raw=trim((string)$raw);if($raw==='')return;$ts=strtotime($raw);if(!$ts||$ts>time()+DAY_IN_SECONDS)return;$c[]=['raw'=>$raw,'ts'=>$ts,'source'=>$source,'score'=>$score];};if(preg_match_all('~<meta\b[^>]*>~i',substr($html,0,450000),$tags))foreach($tags[0] as $tag){if(!preg_match('/(?:property|name|itemprop)=["\']([^"\']+)["\']/i',$tag,$km)||!preg_match('/content=["\']([^"\']+)["\']/i',$tag,$vm))continue;$k=strtolower($km[1]);if('article:published_time'===$k)$add($vm[1],'Open Graph article:published_time',98);elseif(in_array($k,['datepublished','pubdate','publishdate'],true))$add($vm[1],'meta publicatiedatum',94);}if(preg_match_all('~<script[^>]+type=["\']application/ld\+json["\'][^>]*>(.*?)</script>~is',$html,$blocks))foreach($blocks[1] as $raw){$j=json_decode(html_entity_decode($raw,ENT_QUOTES|ENT_HTML5,'UTF-8'),true);$walk=function($v)use(&$walk,$add){if(!is_array($v))return;if(!empty($v['datePublished']))$add((string)$v['datePublished'],'JSON-LD datePublished',100);foreach($v as $x)if(is_array($x))$walk($x);};if(is_array($j))$walk($j);}if(!$c)return ['raw'=>'','ts'=>0,'source'=>'niet gevonden','confidence'=>0];usort($c,fn($a,$b)=>$b['score']<=>$a['score']);$b=$c[0];return ['raw'=>$b['raw'],'ts'=>(int)$b['ts'],'source'=>$b['source'],'confidence'=>(int)$b['score']];}}
if(!function_exists('mvm_ai_agenda_merge_result_v1')){function mvm_ai_agenda_merge_result_v1(array $source,array $event){$url=esc_url_raw($event['url']??$source['url']??'');if(!$url)return false;$start_ts=strtotime((string)($event['start']??''))?:0;if($start_ts&&$start_ts<time()-DAY_IN_SECONDS)return false;$pub=['raw'=>(string)($event['published']??''),'ts'=>strtotime((string)($event['published']??''))?:0,'source'=>'Event JSON-LD datePublished','confidence'=>!empty($event['published'])?96:0];if(!$pub['ts']&&$url){$detail=mvm_ai_agenda_fetch_v1($url);if(!is_wp_error($detail))$pub=mvm_ai_agenda_published_v1($detail);} $id=hash('sha256',strtolower($url));$rows=get_option('mvm_bh_news_radar_results',[]);if(!is_array($rows))$rows=[];foreach($rows as $i=>$r){if(!is_array($r))continue;if((string)($r['id']??'')===$id||(!empty($r['url'])&&rtrim(strtolower((string)$r['url']),'/')===rtrim(strtolower($url),'/'))){if(empty($r['published_ts'])&&!empty($pub['ts'])){$rows[$i]['published_ts']=$pub['ts'];$rows[$i]['published']=$pub['raw'];$rows[$i]['date_source']=$pub['source'];$rows[$i]['date_confidence']=$pub['confidence'];update_option('mvm_bh_news_radar_results',$rows,false);}return false;}}$now=time();$row=['id'=>$id,'track_id'=>$id,'source_id'=>absint($source['id']??0),'source'=>sanitize_text_field((string)($source['name']??'')),'source_url'=>esc_url_raw((string)($source['url']??'')),'title'=>sanitize_text_field((string)($event['title']??'Agenda-item')),'url'=>$url,'published'=>$pub['raw'],'published_ts'=>$pub['ts'],'excerpt'=>mb_substr(sanitize_textarea_field((string)($event['excerpt']??'')),0,3000),'previous_excerpt'=>'','event_type'=>'nieuw','found_at'=>wp_date(DATE_ATOM,$now),'found_ts'=>$now,'local_score'=>0,'ai_pending'=>1,'status'=>'controleren','category'=>'Evenementen / Agenda','summary'=>'','confidence'=>0,'reason'=>'Agenda-item automatisch gevonden; wacht op bestaande Nieuwsradar AI-beoordeling.','change_relevant'=>null,'change_summary'=>'','date_issues'=>$pub['ts']?[]:['Publicatiedatum kon niet betrouwbaar worden gevonden.'],'relative_terms'=>[],'date_source'=>$pub['source'],'date_confidence'=>$pub['confidence'],'date_checked_at'=>wp_date(DATE_ATOM,$now),'reviewed'=>0,'dismissed'=>0,'email_pending'=>0,'email_sent'=>0,'lifecycle'=>'actief','related_post_id'=>0,'relationship_type'=>'geen','agenda_start_ts'=>$start_ts];array_unshift($rows,$row);$legacy=get_option('mvm_bh_news_radar_settings',[]);$keep=max(100,min(1000,absint(is_array($legacy)?($legacy['retention']??500):500)));update_option('mvm_bh_news_radar_results',array_slice($rows,0,$keep),false);return true;}}
if(!function_exists('mvm_ai_agenda_scan_v1')){function mvm_ai_agenda_scan_v1(){ $s=mvm_ai_agenda_settings_v1();if(empty($s['enabled']))return ['added'=>0,'message'=>'AI-agendacrawl staat uit.'];$sources=get_option('mvm_bh_sources',[]);$sources=array_values(array_filter(is_array($sources)?$sources:[],fn($x)=>is_array($x)&&!empty($x['active'])&&empty($x['excluded'])&&!empty($x['url'])));if(!$sources){$s['last_run']=time();$s['last_message']='Geen actieve bronnen met URL.';mvm_ai_agenda_save_settings_v1($s);return ['added'=>0,'message'=>$s['last_message']];}$batch=max(1,min(5,absint($s['batch'])));$cursor=absint($s['cursor'])%count($sources);$added=0;$checked=0;for($n=0;$n<$batch;$n++){ $source=$sources[($cursor+$n)%count($sources)];$html=mvm_ai_agenda_fetch_v1($source['url']);$checked++;if(is_wp_error($html))continue;$events=mvm_ai_agenda_events_v1($html,$source['url']);if(!$events){$agenda=mvm_ai_agenda_discover_v1($html,$source['url']);if($agenda&&$agenda!==$source['url']){$ahtml=mvm_ai_agenda_fetch_v1($agenda);if(!is_wp_error($ahtml))$events=mvm_ai_agenda_events_v1($ahtml,$agenda);}}foreach(array_slice($events,0,3) as $event)if(mvm_ai_agenda_merge_result_v1($source,$event))$added++;}$s['cursor']=($cursor+$batch)%count($sources);$s['last_run']=time();$s['last_message']=$checked.' bron(nen) gecontroleerd; '.$added.' nieuw(e) agenda-item(s) naar de Nieuwsradar AI-wachtrij.';mvm_ai_agenda_save_settings_v1($s);return ['added'=>$added,'checked'=>$checked,'message'=>$s['last_message']];}}
