add_action('rest_api_init',static function(){if(!class_exists('MvM_Hub4_Security')||!class_exists('MvM_Hub4_Capabilities'))return;$manage=MvM_Hub4_Security::require_capability(MvM_Hub4_Capabilities::SOURCE_MANAGE);register_rest_route('mvm-hub4/v1','/agenda-crawl/settings',[['methods'=>WP_REST_Server::READABLE,'permission_callback'=>$manage,'callback'=>static function(){ $s=mvm_ai_agenda_settings_v1();return rest_ensure_response(['enabled'=>!empty($s['enabled']),'radarSort'=>$s['radar_sort'],'lastRun'=>$s['last_run']?wp_date(DATE_ATOM,$s['last_run']):null,'lastMessage'=>$s['last_message']]);}],['methods'=>WP_REST_Server::CREATABLE,'permission_callback'=>$manage,'callback'=>static function(WP_REST_Request $r){$p=(array)$r->get_json_params();$s=mvm_ai_agenda_settings_v1();if(array_key_exists('enabled',$p))$s['enabled']=rest_sanitize_boolean($p['enabled']);if(isset($p['radarSort'])&&in_array($p['radarSort'],['recent','relevance','radar'],true))$s['radar_sort']=$p['radarSort'];mvm_ai_agenda_save_settings_v1($s);mvm_ai_agenda_schedule_v1();return rest_ensure_response(['ok'=>true,'enabled'=>!empty($s['enabled']),'radarSort'=>$s['radar_sort']]);}]]);register_rest_route('mvm-hub4/v1','/agenda-crawl/run',['methods'=>WP_REST_Server::CREATABLE,'permission_callback'=>$manage,'callback'=>static function(){ $s=mvm_ai_agenda_settings_v1();if(empty($s['enabled']))return new WP_Error('mvm_agenda_disabled','Zet AI-agendacrawl eerst aan.',['status'=>400]);return rest_ensure_response(mvm_ai_agenda_scan_v1());}]);});
add_filter('rest_post_dispatch',static function($response,$server,$request){if(!$response instanceof WP_REST_Response||'/mvm-hub4/v1/news-radar'!==$request->get_route())return $response;$data=$response->get_data();if(!is_array($data)||empty($data['items'])||!is_array($data['items']))return $response;$mode=mvm_ai_agenda_settings_v1()['radar_sort']??'recent';if('radar'===$mode)return $response;$ts=static function($g){$p=is_array($g['primary']??null)?$g['primary']:[];return absint($p['published_ts']??0)?:absint($p['found_ts']??0)?:strtotime((string)($p['found_at']??''))?:0;};usort($data['items'],static function($a,$b)use($mode,$ts){if('relevance'===$mode){$as=absint($a['primary']['local_score']??0);$bs=absint($b['primary']['local_score']??0);if($as!==$bs)return $bs<=>$as;}return $ts($b)<=>$ts($a);});$response->set_data($data);return $response;},20,3);